/*
	Получение синуса методом кусочно-линейной аппроксимации
	по табличным значениям.
	Использует умножение с 32-битным результатом, которое есть в cortex-M0
	(не использует DSP инструкции, которые есть начиная с cortex-M3).
	Уровень гармоник с интерполяцией заметно ниже (-142dB), чем без неё

*/

#define FRACTION_MUL_BIT 12

int32_t get_sine32_linear(uint32_t angle)
{
	int neg = 0;
	if(angle & 0x80000000)
	{
		// переводим из 2-4 квадранта в 1-2.
		neg = 1;
		angle &= 0x7fffffff;
	}

	// переводим в 1-й квадрант
	if(angle > 0x40000000) angle = 0x80000000 - angle;

	// angle теперь в диапазоне 0 .. 0x40000000 (30 бит)

	int idx = angle >> (30 - SINE_QTABLE_POW); // idx = 0..2048
	int32_t ret;

	if(idx == (1 << SINE_QTABLE_POW)) ret = sine_approx_4097_0_q1[idx]; // строго 90 градусов
	else
	{
		ret = sine_approx_4097_0_q1[idx];
		uint32_t dy = sine_approx_4097_0_q1[idx + 1] - ret;
		// dy будет максимум 0x000C90FD при таблице 4097, т.е. 20 младших бита
		uint32_t mul = angle << (2 + SINE_QTABLE_POW) >> (32 - FRACTION_MUL_BIT); // дробная часть угла 12 бит
		ret += (dy * mul) >> FRACTION_MUL_BIT; //после умножения нормализуем на эти 12 бит дробной части угла
	}

	return neg ? -ret : ret;

}
